import { Injectable } from '@angular/core';
import {
	IIntegration,
	IIntegrationFilter,
	IIntegrationGroup,
	IIntegrationGroupTypeOption,
	IntegrationTypeEnum,
	IntegrationTypeGroupEnum
} from '@gauzy/contracts';
import { BehaviorSubject, EMPTY, Observable, of } from 'rxjs';
import { IntegrationsService } from './integrations.service';
import { tap, map, distinctUntilChanged, debounceTime, catchError, finalize, mergeMap } from 'rxjs/operators';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { ErrorHandlingService } from '../notification';

export const InitialFilter: IIntegrationFilter = {
	integrationTypeId: '',
	searchQuery: '',
	filter: 'all'
};

@UntilDestroy()
@Injectable({
	providedIn: 'root'
})
export class IntegrationsStoreService {
	private _integrations$: BehaviorSubject<IIntegration[]> = new BehaviorSubject([]);
	public integrations$: Observable<IIntegration[]> = this._integrations$.asObservable();

	private _integrationGroups$: BehaviorSubject<IIntegrationGroup[]> = new BehaviorSubject([]);
	public integrationGroups$: Observable<IIntegrationGroup[]> = this._integrationGroups$.asObservable();

	private _isLoading$: BehaviorSubject<boolean> = new BehaviorSubject(false);
	public isLoading$: Observable<boolean> = this._isLoading$.asObservable();

	private _selectedIntegrationTypeId$: BehaviorSubject<string> = new BehaviorSubject(InitialFilter.integrationTypeId);
	public selectedIntegrationTypeId$: Observable<string> = this._selectedIntegrationTypeId$.asObservable();

	private _selectedIntegrationFilter$: BehaviorSubject<string> = new BehaviorSubject(InitialFilter.filter);
	public selectedIntegrationFilter$: Observable<string> = this._selectedIntegrationFilter$.asObservable();

	private _filters$: BehaviorSubject<IIntegrationFilter> = new BehaviorSubject(InitialFilter);

	constructor(
		private _integrationsService: IntegrationsService,
		private _errorHandlingService: ErrorHandlingService
	) {
		this._loadIntegrationGroups();
		this._loadIntegrations();
	}

	private _loadIntegrations() {
		this._filters$
			.pipe(
				distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b)),
				debounceTime(300),
				mergeMap(({ integrationTypeId, searchQuery, filter }) => {
					return integrationTypeId
						? this._integrationsService.fetchIntegrations(integrationTypeId, searchQuery, filter)
						: of([] as IIntegration[]);
				}),
				tap((integrations) => this._integrations$.next(integrations)),
				catchError((error) => {
					this._errorHandlingService.handleError(error);
					return of([] as IIntegration[]);
				}),
				untilDestroyed(this)
			)
			.subscribe();
	}

	private _loadIntegrationGroups() {
		this._integrationsService
			.fetchIntegrationGroups()
			.pipe(
				distinctUntilChanged(),
				tap(() => this._isLoading$.next(true)),
				tap((integrationGroups) => this._integrationGroups$.next(integrationGroups)),
				map((integrationGroups) => this._mapToDefaultType(integrationGroups)),
				tap((integrationType) => this._selectedIntegrationTypeId$.next(integrationType.id)),
				tap((integrationType) =>
					this._filters$.next({
						integrationTypeId: integrationType.id,
						searchQuery: '',
						filter: 'all'
					})
				),
				catchError((error) => {
					this._errorHandlingService.handleError(error);
					return EMPTY;
				}),
				finalize(() => this._isLoading$.next(false)),
				untilDestroyed(this)
			)
			.subscribe();
	}

	private _mapToDefaultType(integrationGroups: IIntegrationGroup[]): IIntegrationGroupTypeOption {
		const featuredGroup = integrationGroups.find(
			({ groupName }) => groupName === IntegrationTypeGroupEnum.FEATURED
		);
		const defaultType =
			featuredGroup?.integrationTypes.find((item) => item.name === IntegrationTypeEnum.ALL_INTEGRATIONS) ??
			integrationGroups[0]?.integrationTypes[0];

		if (!defaultType) {
			throw new Error('No integration groups available');
		}

		return defaultType;
	}

	setSelectedIntegrationTypeId(integrationTypeId: string) {
		this._selectedIntegrationTypeId$.next(integrationTypeId);
		const filterState = this._filters$.getValue();
		this._filters$.next({ ...filterState, integrationTypeId });
	}

	setSelectedIntegrationFilter(filter: string) {
		this._selectedIntegrationFilter$.next(filter);
		const filterState = this._filters$.getValue();
		this._filters$.next({ ...filterState, filter });
	}

	searchIntegration(searchQuery: string) {
		const filterState = this._filters$.getValue();
		this._filters$.next({ ...filterState, searchQuery });
	}

	/*
	 * Clear integration store filters
	 */
	clearFilters() {
		this.setSelectedIntegrationFilter(InitialFilter.filter);

		const integrationGroups = this._integrationGroups$.getValue();
		const integrationType = this._mapToDefaultType(integrationGroups);
		this.setSelectedIntegrationTypeId(integrationType.id);

		this.searchIntegration(InitialFilter.searchQuery);
	}
}
